// postRoutes.js
const express = require('express');
// mergeParams allows access to userId from the parent router
const router = express.Router({ mergeParams: true });

router.get('/:postId', (req, res) => {
  res.send(`Getting post ${req.params.postId} for user ${req.params.userId}`);
});

module.exports = router;

